# The configs of a node behind a Cloudflare Tunnel, shared by deploy/macos/install.sh
# and deploy/linux/install.sh. One copy, so the limits in front of the node cannot
# drift apart between hosts. Sourced, not run. Expects REPO, PREFIX, DOMAIN,
# ALIASES, NODE_PORT, NGINX_PORT, TUNNEL_ID and GENERATOR (the script's name).

render_nginx() {
  cat <<EOF
# Generated by eidchain $GENERATOR. Do not edit; change eidchain.env and re-run.
# Behind cloudflared, so plain HTTP on loopback. The locations follow
# deploy/nginx-eidchain.conf, without /login/: TLS ends at Cloudflare, so a
# client certificate never reaches this server.
daemon off;
worker_processes 1;
pid $PREFIX/state/nginx/nginx.pid;
error_log $PREFIX/logs/nginx.error.log warn;
events { worker_connections 256; }

http {
    include $PREFIX/etc/mime.types;
    default_type application/octet-stream;
    access_log off;                  # no client addresses on success paths
    server_tokens off;
    client_body_temp_path $PREFIX/state/nginx/body;
    proxy_temp_path $PREFIX/state/nginx/proxy;
    fastcgi_temp_path $PREFIX/state/nginx/fastcgi;
    uwsgi_temp_path $PREFIX/state/nginx/uwsgi;
    scgi_temp_path $PREFIX/state/nginx/scgi;

    # Every request comes from cloudflared on loopback. Without this the write
    # limit below would be one bucket shared by the whole internet.
    set_real_ip_from 127.0.0.1;
    real_ip_header CF-Connecting-IP;

    map \$request_method \$eidchain_write_key {
        POST    \$binary_remote_addr;
        default "";
    }
    limit_req_zone \$eidchain_write_key zone=eidchain_write:10m rate=30r/m;

    server {
        listen 127.0.0.1:$NGINX_PORT;
        server_name $DOMAIN ${ALIASES:-};
        root $PREFIX/www;
        index index.html;

        location / {
            add_header Content-Security-Policy "default-src 'none'; script-src 'self'; style-src 'self'; img-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'" always;
            add_header Strict-Transport-Security "max-age=31536000" always;
            add_header X-Content-Type-Options "nosniff" always;
            add_header Referrer-Policy "no-referrer" always;
            add_header Cache-Control "no-cache" always;
            try_files \$uri \$uri/ =404;
        }

        location /signer/ {
            add_header Content-Security-Policy "default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'none'; img-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'" always;
            add_header Strict-Transport-Security "max-age=31536000" always;
            add_header X-Content-Type-Options "nosniff" always;
            add_header Referrer-Policy "no-referrer" always;
            add_header Cache-Control "no-cache" always;
            try_files \$uri \$uri/ =404;
        }

        location = /chain {
            return 301 /chain/;
        }

        location = /chain/api/v1/blocks {
            client_max_body_size 9m;
            limit_req zone=eidchain_write burst=30 nodelay;
            limit_req_status 429;
            proxy_pass http://127.0.0.1:$NODE_PORT/api/v1/blocks;
            proxy_set_header Host \$host;
            proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
            proxy_set_header X-Forwarded-Proto https;
            add_header Strict-Transport-Security "max-age=31536000" always;
        }

        location /chain/ {
            client_max_body_size 300k;
            limit_req zone=eidchain_write burst=30 nodelay;
            limit_req_status 429;
            proxy_pass http://127.0.0.1:$NODE_PORT/;
            proxy_set_header Host \$host;
            proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
            proxy_set_header X-Forwarded-Proto https;
            proxy_read_timeout 90s;      # payload submission waits for the OCSP responder
            add_header Strict-Transport-Security "max-age=31536000" always;
        }
    }
}
EOF
}

render_tunnel() {
  cat <<EOF
# Generated by eidchain $GENERATOR. Do not edit; change eidchain.env and re-run.
tunnel: $TUNNEL_ID
credentials-file: $PREFIX/secrets/cloudflared/$TUNNEL_ID.json
ingress:
EOF
  local h
  for h in $DOMAIN ${ALIASES:-}; do
    printf '  - hostname: %s\n    service: http://127.0.0.1:%s\n' "$h" "$NGINX_PORT"
  done
  echo "  - service: http_status:404"
}

# render_www DIR: the site without the card-login page, which cannot work here.
render_www() {
  local dir=$1
  mkdir -p "$dir"
  rsync -a --delete --exclude login/ "$REPO/www/" "$dir/"
  sed -e "s|<p class=\"eyebrow\">eidchain.ivoras.net</p>|<p class=\"eyebrow\">$DOMAIN</p>|" \
    -e '/href="\/login\/"/d' "$dir/index.html" >"$dir/index.html.new"
  mv "$dir/index.html.new" "$dir/index.html"
}
